package com.weiwei.wificast;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.util.DisplayMetrics;import android.view.WindowManager;import java.io.*;import java.net.*;import java.nio.*;import java.security.SecureRandom;import java.util.Locale;

public class CastService extends Service {
 static volatile boolean running=false;static volatile String token="";static final int PORT=17867; volatile byte[] frame; MediaProjection projection;VirtualDisplay display;ImageReader reader;HandlerThread worker;ServerSocket server;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(running)return START_NOT_STICKY;if(intent==null){stopSelf();return START_NOT_STICKY;}
  try{NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("cast","屏幕投屏",NotificationManager.IMPORTANCE_LOW));Notification n=new Notification.Builder(this,"cast").setContentTitle("正在投屏").setContentText("点击返回投屏应用，停止投屏请在应用内操作").setSmallIcon(android.R.drawable.presence_video_online).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();if(Build.VERSION.SDK_INT>=29)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(1,n);
  byte[] key=new byte[16];new SecureRandom().nextBytes(key);StringBuilder s=new StringBuilder();for(byte b:key)s.append(String.format(Locale.US,"%02x",b&255));token=s.toString();
  Intent data=(Intent)intent.getParcelableExtra("data");int result=intent.getIntExtra("result",0);projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(result,data);worker=new HandlerThread("capture");worker.start();Handler handler=new Handler(worker.getLooper());projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},handler);
  DisplayMetrics dm=new DisplayMetrics();((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRealMetrics(dm);int w=dm.widthPixels,h=dm.heightPixels;float scale=Math.min(1f,960f/Math.max(w,h));w=Math.max(2,((int)(w*scale))&~1);h=Math.max(2,((int)(h*scale))&~1);final int fw=w,fh=h;
  reader=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(r->{Image im=null;Bitmap padded=null,trim=null;try{im=r.acquireLatestImage();if(im==null)return;Image.Plane p=im.getPlanes()[0];ByteBuffer buf=p.getBuffer();int pixel=p.getPixelStride(),row=p.getRowStride();padded=Bitmap.createBitmap(fw+(row-pixel*fw)/pixel,fh,Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(buf);trim=Bitmap.createBitmap(padded,0,0,fw,fh);ByteArrayOutputStream out=new ByteArrayOutputStream();trim.compress(Bitmap.CompressFormat.JPEG,65,out);frame=out.toByteArray();}catch(Exception ignored){}finally{if(trim!=null&&trim!=padded)trim.recycle();if(padded!=null)padded.recycle();if(im!=null)im.close();}},handler);
  display=projection.createVirtualDisplay("WiFiCast",w,h,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);server=new ServerSocket(PORT);running=true;new Thread(this::accept).start();return START_NOT_STICKY;
 }catch(Exception e){android.util.Log.e("WiFiCast","start failed",e);stopSelf();return START_NOT_STICKY;}}
 void accept(){while(running){try{Socket sock=server.accept();sock.setSoTimeout(5000);new Thread(()->serve(sock)).start();}catch(Exception e){break;}}}
 void serve(Socket sock){try(Socket s=sock){BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream()));String first=in.readLine();if(first==null)return;String[] parts=first.split(" ");if(parts.length<2)return;String path=parts[1].split("\\?")[0];String line;while((line=in.readLine())!=null&&!line.isEmpty()){}OutputStream out=s.getOutputStream();String base="/"+token;if(path.equals(base)||path.equals(base+"/")){String html="<!doctype html><html lang=zh><meta name=viewport content='width=device-width,initial-scale=1'><title>手机无线投屏</title><style>body{margin:0;background:#0c1321;color:white;font:16px sans-serif;text-align:center}header{padding:16px}img{max-width:100%;height:calc(100vh - 100px);object-fit:contain}button{padding:8px 14px}</style><header>手机无线投屏　<button onclick='document.documentElement.requestFullscreen()'>全屏观看</button></header><img src='"+base+"/stream'><p>结束时请在手机上点击停止投屏</p></html>";byte[] bytes=html.getBytes("UTF-8");out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: no-store\r\nContent-Length: "+bytes.length+"\r\n\r\n").getBytes("UTF-8"));out.write(bytes);out.flush();}else if(path.equals(base+"/stream")){out.write("HTTP/1.1 200 OK\r\nCache-Control: no-store\r\nContent-Type: multipart/x-mixed-replace; boundary=frame\r\n\r\n".getBytes("UTF-8"));while(running&&!s.isClosed()){byte[] f=frame;if(f!=null){out.write(("--frame\r\nContent-Type: image/jpeg\r\nContent-Length: "+f.length+"\r\n\r\n").getBytes("UTF-8"));out.write(f);out.write("\r\n".getBytes("UTF-8"));out.flush();}Thread.sleep(100);}}else{out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n".getBytes("UTF-8"));}}catch(Exception ignored){}}
 public void onDestroy(){running=false;try{if(server!=null)server.close();}catch(Exception ignored){}if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null){MediaProjection p=projection;projection=null;p.stop();}if(worker!=null)worker.quitSafely();frame=null;token="";super.onDestroy();}
}
